package com.pulsefit.member;
import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/members") public class MemberController { private final MemberRepository repo; public MemberController(MemberRepository r){repo=r;} @GetMapping public List<Member> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Member> get(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @GetMapping("/internal/{id}") public ResponseEntity<Member> internal(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}
 @PostMapping public ResponseEntity<?> create(@RequestBody Member m){if(repo.existsByEmail(m.getEmail()))return ResponseEntity.status(409).body(Map.of("message","Email already exists")); return ResponseEntity.status(201).body(repo.save(m));} @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody Member input){return repo.findById(id).map(m->{m.setName(input.getName());m.setEmail(input.getEmail());m.setPhone(input.getPhone());m.setDateOfBirth(input.getDateOfBirth());m.setStatus(input.getStatus());return ResponseEntity.ok(repo.save(m));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }
